-- ── util.uuid_v7() ─────────────────────────────────────────────────────────────────────────────
-- PostgreSQL 16 has no built-in UUIDv7. RFC 9562 layout: 48-bit Unix epoch milliseconds, then a v4
-- UUID's random bits with the version nibble set to 7 (bits 52,53) and the variant (10) kept.
-- IDs are non-enumerable and time-sortable to the millisecond (TARGET_ARCHITECTURE §4).
CREATE FUNCTION "util"."uuid_v7"() RETURNS uuid
LANGUAGE sql VOLATILE PARALLEL SAFE
AS $fn$
  SELECT encode(
    set_bit(
      set_bit(
        overlay(uuid_send(gen_random_uuid())
                PLACING substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
                FROM 1 FOR 6),
        52, 1),
      53, 1),
    'hex')::uuid;
$fn$;

